import { Link, useLocation } from 'react-router-dom';

const navItems = [
    { path: '/dashboard', icon: 'dashboard', label: 'Overview' },
    { path: '/devices', icon: 'devices', label: 'Devices' },
];

function Sidebar() {
    const location = useLocation();

    return (
        <aside className="fixed left-0 top-0 h-full w-72 bg-surface-container-lowest z-50 flex flex-col border-r border-glass-stroke backdrop-blur-xl">

            {/* Logo */}
            <div className="p-6 flex items-center gap-3 mb-2">
                <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-electric-blue to-vibrant-violet flex items-center justify-center text-lg font-bold text-white shadow-lg">
                    ⚡
                </div>
                <span className="text-title-md font-inter font-medium text-on-surface">
                    WattWise
                </span>
            </div>

            {/* Navigation */}
            <nav className="flex-1 px-6 mt-2 space-y-1">
                {navItems.map((item) => {
                    const isActive = location.pathname === item.path;
                    return (
                        <Link
                            key={item.path}
                            to={item.path}
                            className={`
                                flex items-center px-4 py-3 rounded-lg transition-all duration-200 group
                                ${isActive
                                    ? 'bg-secondary-container text-on-secondary-container glow-violet'
                                    : 'text-on-surface-variant hover:bg-surface-container-highest hover:text-on-surface'
                                }
                            `}
                        >
                            <span className={`material-symbols-outlined mr-3 ${
                                isActive ? 'text-vibrant-violet' : 'group-hover:text-electric-blue'
                            }`}>
                                {item.icon}
                            </span>
                            <span className="font-inter text-body-md">
                                {item.label}
                            </span>
                        </Link>
                    );
                })}
            </nav>

            {/* System Status */}
            <div className="px-6 py-6 border-t border-glass-stroke">
                <div className="p-4 rounded-xl bg-surface-container-high/50 backdrop-blur-md flex items-center gap-3">
                    <div className="w-2 h-2 rounded-full bg-electric-blue animate-pulse" />
                    <span className="text-label-caps font-inter text-on-surface-variant uppercase">
                        System: Optimal
                    </span>
                </div>
            </div>

        </aside>
    );
}

export default Sidebar;
